def emit(text: str, code: int) -> int:
    sys.stdout.write(text)
    return code


def resource_path(name: str) -> Path:
    return Path(__file__).resolve().parent / "resources" / name


def read_resource(name: str) -> str:
    return resource_path(name).read_text(encoding="utf-8")


def first_special(args: list[str]) -> str | None:
    for arg in args:
        kind = SPECIAL_FLAGS.get(arg)
        if kind is not None:
            return kind
    return None


def is_integer(text: str) -> bool:
    return re.fullmatch(r"[+-]?\d+", text) is not None


def load_stdin() -> str:
    if not hasattr(load_stdin, "_cache"):
        load_stdin._cache = sys.stdin.read()
    return load_stdin._cache


def path_exists(raw: str) -> bool:
    return Path(raw).exists()


def is_dir(raw: str) -> bool:
    return Path(raw).is_dir()


def file_lines_from_path(raw: str) -> list[str]:
    return Path(raw).read_text(encoding="utf-8").splitlines()


def validate_integer_option(opt: str, value: str) -> int | None:
    if not is_integer(value):
        sys.stdout.write(f"cppcheck: error: argument to '{opt}' is not valid - not an integer.\n")
        return None
    return int(value)


def validate_enable_disable(kind: str, value: str) -> int | None:
    if value == "":
        return emit(f"cppcheck: error: --{kind} parameter is empty\n", 1)
    for name in value.split(","):
        if name not in ENABLE_DISABLE_NAMES:
            return emit(f"cppcheck: error: --{kind} parameter with the unknown name '{name}'\n", 1)
    return None


def validate_project(raw: str) -> tuple[bool, bool, bool] | int:
    if not path_exists(raw):
        return emit(f"cppcheck: error: failed to open project '{raw}'. The file does not exist.\n", 1)

    lower = raw.lower()
    if lower.endswith(".sln") or lower.endswith(".vcxproj"):
        return True, True, True
    if lower.endswith(".bpr"):
        return True, False, True

    try:
        data = json.loads(Path(raw).read_text(encoding="utf-8"))
    except Exception:
        return emit(
            f"cppcheck: error: compilation database is not a JSON array\n"
            f"cppcheck: error: failed to load project '{raw}'. An error occurred.\n",
            1,
        )

    if not isinstance(data, list):
        return emit(
            f"cppcheck: error: compilation database is not a JSON array\n"
            f"cppcheck: error: failed to load project '{raw}'. An error occurred.\n",
            1,
        )

    return True, False, bool(data)


def validate_suppress_xml(raw: str) -> int | None:
    path = Path(raw)
    if not path.exists():
        return emit(f"cppcheck: error: failed to load suppressions XML '{raw}' (XML_ERROR_FILE_NOT_FOUND).\n", 1)

    if path.read_bytes() == b"":
        return emit(f"cppcheck: error: failed to load suppressions XML '{raw}' (XML_ERROR_EMPTY_DOCUMENT).\n", 1)

    try:
        ET.parse(path)
    except ET.ParseError:
        return emit(f"cppcheck: error: failed to load suppressions XML '{raw}' (XML_ERROR_PARSING_ELEMENT).\n", 1)

    return None


def count_file_list_entries(raw: str) -> int | int:
    if raw == "-":
        lines = load_stdin().splitlines()
        return sum(1 for line in lines if line.strip())

    if not path_exists(raw):
        return emit(f'cppcheck: error: couldn\'t open the file: "{raw}".\n', 1)

    lines = file_lines_from_path(raw)
    return sum(1 for line in lines if line.strip())


def require_existing_file(raw: str, message: str) -> int | None:
    if not path_exists(raw):
        return emit(message.format(raw=raw), 1)
    return None


def consume_next_value(args: list[str], index: int, opt: str, missing_message: str) -> tuple[str, int] | int:
    if index + 1 >= len(args) or args[index + 1].startswith("-"):
        return emit(missing_message, 1)
    return args[index + 1], index + 2


